     1	package hotel.documents;
     2	
     3	import hotel.reservations.GuestType;
     4	import hotel.reservations.Reservation;
     5	import hotel.rooms.Room;
     6	import hotel.rooms.RoomType;
     7	import java.math.BigDecimal;
     8	import java.time.LocalDate;
     9	
    10	/** The receipt the guest gets when the reservation is confirmed, at check-out, and on request. */
    11	public record ReservationReceipt(
    12	        String title,
    13	        long reservationId,
    14	        String guestName,
    15	        String guestCpf,
    16	        String companyCnpj,
    17	        String companyName,
    18	        String guestPassport,
    19	        String guestCountry,
    20	        int roomNumber,
    21	        RoomType roomType,
    22	        LocalDate checkIn,
    23	        LocalDate checkOut,
    24	        int nights,
    25	        BigDecimal subtotal,
    26	        BigDecimal discount,
    27	        BigDecimal total,
    28	        String text) {
    29	
    30	    public ReservationReceipt(Reservation reservation, Room room) {
    31	        this(
    32	                titleFor(reservation.guest().type()),
    33	                reservation.id(),
    34	                reservation.guest().name(),
    35	                reservation.guest().cpf(),
    36	                reservation.guest().companyCnpj(),
    37	                reservation.guest().companyName(),
    38	                reservation.guest().passport(),
    39	                reservation.guest().country(),
    40	                room.number(),
    41	                room.type(),
    42	                reservation.checkIn(),
    43	                reservation.checkOut(),
    44	                reservation.price().nights(),
    45	                reservation.price().subtotal(),
    46	                reservation.price().discount(),
    47	                reservation.price().total(),
    48	                generateText(
    49	                        reservation.guest().type(),
    50	                        reservation.id(),
    51	                        reservation.guest().name(),
    52	                        reservation.guest().cpf(),
    53	                        reservation.guest().companyCnpj(),
    54	                        reservation.guest().companyName(),
    55	                        reservation.guest().passport(),
    56	                        reservation.guest().country(),
    57	                        room.number(),
    58	                        room.type(),
    59	                        reservation.checkIn(),
    60	                        reservation.checkOut(),
    61	                        reservation.price().nights(),
    62	                        reservation.price().subtotal(),
    63	                        reservation.price().discount(),
    64	                        reservation.price().total()));
    65	    }
    66	
    67	    private static String titleFor(GuestType guestType) {
    68	        return switch (guestType) {
    69	            case INDIVIDUAL -> "Comprovante de reserva";
    70	            case COMPANY -> "Fatura de hospedagem";
    71	            case FOREIGN -> "Booking receipt";
    72	        };
    73	    }
    74	
    75	    private static String generateText(
    76	            GuestType guestType,
    77	            long reservationId,
    78	            String guestName,
    79	            String guestCpf,
    80	            String companyCnpj,
    81	            String companyName,
    82	            String guestPassport,
    83	            String guestCountry,
    84	            int roomNumber,
    85	            RoomType roomType,
    86	            LocalDate checkIn,
    87	            LocalDate checkOut,
    88	            int nights,
    89	            BigDecimal subtotal,
    90	            BigDecimal discount,
    91	            BigDecimal total) {
    92	        return switch (guestType) {
    93	            case INDIVIDUAL -> generateIndividualReceipt(
    94	                    reservationId, guestName, guestCpf, roomNumber, roomType, checkIn, checkOut, nights, subtotal,
    95	                    discount, total);
    96	            case COMPANY -> generateCompanyInvoice(
    97	                    reservationId, companyName, companyCnpj, guestName, roomNumber, roomType, checkIn, checkOut,
    98	                    nights, subtotal, discount, total);
    99	            case FOREIGN -> generateForeignReceipt(
   100	                    reservationId, guestName, guestPassport, guestCountry, roomNumber, roomType, checkIn, checkOut,
   101	                    nights, subtotal, discount, total);
   102	        };
   103	    }
   104	
   105	    private static String generateIndividualReceipt(
   106	            long reservationId,
   107	            String guestName,
   108	            String guestCpf,
   109	            int roomNumber,
   110	            RoomType roomType,
   111	            LocalDate checkIn,
   112	            LocalDate checkOut,
   113	            int nights,
   114	            BigDecimal subtotal,
   115	            BigDecimal discount,
   116	            BigDecimal total) {
